import { createContext, useContext } from "react";

export interface ComboboxInteractionContextType {
  clearValue: () => void;
  onQueryChange?: (query: string) => void;
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
}

export const ComboboxInteractionContext = createContext<ComboboxInteractionContextType | undefined>(
  undefined,
);

export const useComboboxInteraction = () => {
  const context = useContext(ComboboxInteractionContext);
  if (!context) {
    throw new Error("useComboboxInteraction must be used within a Combobox component");
  }
  return context;
};
